    hs = [r for r in range(h) if all(v == 8 for v in grid[r])]
    vs = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb = [-1] + hs + [h]
    cb = [-1] + vs + [w]
    out = [row[:] for row in grid]
    # Adjacent compartments form reflected pairs. Transfer each motif into
    # an empty neighboring compartment, reversing the axis across the divider.
    for i in range(len(rb)-1):
        r0, r1 = rb[i]+1, rb[i+1]
        for j in range(len(cb)-1):
            c0, c1 = cb[j]+1, cb[j+1]
            # vertically mirror compartment into its neighbor above/below
            for ii in (i-1, i+1):
                if not 0 <= ii < len(rb)-1: continue
                q0, q1 = rb[ii]+1, rb[ii+1]
                n = min(r1-r0, q1-q0)
                for d in range(n):
                    sr = r1-1-d if ii < i else r0+d
                    tr = q0+d if ii < i else q1-1-d
                    for c in range(c0, c1):
                        if grid[sr][c] not in (0,8) and grid[tr][c] == 0:
                            out[tr][c] = grid[sr][c]
            # horizontally mirror into neighboring compartment
            for jj in (j-1, j+1):
                if not 0 <= jj < len(cb)-1: continue
                q0, q1 = cb[jj]+1, cb[jj+1]
                n = min(c1-c0, q1-q0)
                for d in range(n):
                    sc = c1-1-d if jj < j else c0+d
                    tc = q0+d if jj < j else q1-1-d
                    for r in range(r0, r1):
                        if grid[r][sc] not in (0,8) and grid[r][tc] == 0:
                            out[r][tc] = grid[r][sc]
    return out

